parameters.jsCode:
// Normalise the agent's structured output into the exact shape the downstream
// human-in-the-loop nodes already expect (caseId, verdict, confidence, ...).
const c = $('Extract case').item.json;
let out = $json.output;
if (typeof out === 'string') {
  let t = out.trim().replace(/^```(json)?/i, '').replace(/```$/, '').trim();
  try { out = JSON.parse(t); } catch (e) {
    out = { verdict: 'escalate', confidence: 0, analysis: String($json.output).slice(0, 600), reasons: [], recommended_actions: [] };
  }
}
out = out || {};
const verdict = out.verdict === 'false_positive' ? 'false_positive' : 'escalate';
return [{ json: {
  caseId: c.caseId,
  title: c.title,
  verdict,
  confidence: Number(out.confidence) || 0,
  analysis: out.analysis || 'No analysis produced.',
  reasons: Array.isArray(out.reasons) ? out.reasons : [],
  actions: Array.isArray(out.recommended_actions) ? out.recommended_actions : [],
} }];
